import { VOICES } from '../../construction-two/audio/voices.js'
// A namespace import rather than named ones, on purpose. calibration.js is
// generated by a tool that imports this file, so a named import of something
// the current calibration.js does not export yet is a syntax error that stops
// the tool running and regenerating it — a deadlock every time a bed is added.
// Unity is the right fallback: uncalibrated means "play it as written", not
// "fail".
import * as CAL from './calibration.js'
import {
  audioState,
  bed,
  configureAudio,
  createChain,
  dbToGain,
  hasPref,
  isAudible,
  setEnabled,
  sound,
  subscribe,
  teardownAudio,
  toggleEnabled,
} from '../../../audio/engine.js'

/**
 * This route's mix: which moments exist, what each sounds like, and exactly
 * how loud it ends up.
 *
 * The machinery — context, buses, ceiling, cooldowns, preference, unlock —
 * is `src/audio/engine.js`, already shared by /construction-two and
 * /education. The voices are /construction-two's, unchanged and imported
 * rather than copied: that palette was built from noise and filters to be a
 * building site in the first place, and concrete, structural, metal and
 * mechanical are exactly the four textures this page needs. Writing a second
 * set would have produced the same sounds with different bugs.
 *
 * THE STORY, AS A MIX
 *
 * Read down the peak column and the sequence is there:
 *
 *   empty      nothing but room tone, 41 dB down. The site is quiet because
 *              nothing is happening on it yet.
 *   survey     small, dry, repetitive — a stake and a length of string are
 *              the least dramatic sounds on the page, and should be
 *   opening    one structural hit at -15, the loudest moment here, because
 *              the ground giving way is the event the whole page is built
 *              toward
 *   earthwork  the ground coming away and landing on the heaps, over a low
 *              bed that rises and falls with how fast the cut is advancing —
 *              none of it as loud as the break that started it
 *
 * Nothing announces itself twice. If a sound is noticeable every time it
 * happens it is too loud.
 */

const CALIBRATION = CAL.CALIBRATION ?? {}
const AMBIENCE_TRIM = CAL.AMBIENCE_TRIM ?? 1
const EARTH_TRIM = CAL.EARTH_TRIM ?? 1

/* -------------------------------------------------------------------- mix */

const BUS_LEVELS = {
  ambience: 0.20,
  interaction: 0.30,
  works: 0.26,
  transitions: 0.22,
}

const MASTER = 0.15

/** The sustained layers, in dBFS at the speaker. Both are felt, not heard. */
const AMBIENCE_PEAK = -41
const EARTH_PEAK = -28

/**
 * `peak` is the target peak of this sound AT THE SPEAKER, in dBFS, after the
 * bus and the master have been applied — not a bare gain, which means nothing
 * until you have also traced the bus, the master and the loudness of the
 * source. Written this way the table is the mix.
 *
 * `calibration.js` is generated by `tools/calibrate_site_audio.mjs`, which
 * renders every sound below through this exact graph and works out the
 * correction that makes it hit the number written here. Change a voice or a
 * target, re-run the tool, commit the result.
 */
const SOUNDS = {
  /* the kit arriving ---------------------------------------------------- */
  // Once. A tripod being set up is a mechanism, and it is the only mechanical
  // sound on the page until the machine turns up.
  'kit.set':      { voice: 'mechanical', bus: 'transitions', peak: -19, cooldown: 1200, vary: 0.08, dur: 0.42 },

  /* the setout ----------------------------------------------------------- */
  // Twelve stakes and twelve lines, on cooldowns short enough that a fast
  // scroll still gives each one its own sound rather than collapsing the
  // whole setout into two taps. They are quiet because they are small: this
  // is the least dramatic work on the page and should sound like it.
  'stake.drive':  { voice: 'concrete',   bus: 'works',       peak: -22, cooldown: 45,  vary: 0.16 },
  'line.pull':    { voice: 'air',        bus: 'works',       peak: -26, cooldown: 60,  vary: 0.20 },
  'setout.done':  { voice: 'resolved',   bus: 'transitions', peak: -18, cooldown: 2000 },

  /* the ground opening ---------------------------------------------------- */
  // The loudest thing on the page, and the only one at -15. Everything before
  // it is measurement and everything after it is routine; this is the moment
  // the site stops being a drawing.
  'ground.break': { voice: 'structural', bus: 'works',       peak: -15, cooldown: 1500, vary: 0.06 },
  // Earth coming away behind the front. Fired from marks spread across the
  // sweep, so scrolling slowly gives separate falls and scrolling fast gives
  // a continuous crumble — which is what the picture is doing either way.
  'ground.work':  { voice: 'concrete',   bus: 'works',       peak: -21, cooldown: 90,  vary: 0.22 },

  /* the earth coming out ---------------------------------------------------- */
  // Spoil landing on the heaps. Quiet and frequent — this is the sound of the
  // excavation having somewhere to go, not an event in its own right.
  'spoil.fall':   { voice: 'concrete',   bus: 'works',       peak: -24, cooldown: 130, vary: 0.26 },

  /* and it stops ----------------------------------------------------------- */
  'site.settle':  { voice: 'resolved',   bus: 'transitions', peak: -19, cooldown: 2500, rate: 0.92 },

  /* the one press the visitor makes ------------------------------------------ */
  'ui.click':     { voice: 'click',      bus: 'interaction', peak: -20, cooldown: 150, vary: 0.18, weight: 0.4 },
}

/* The only id that survives prefers-reduced-motion: a press the user made. */
const ESSENTIAL = new Set(['ui.click'])

const STORAGE_KEY = 'bytes:sound'
const MANIFEST = '/assets/construction/audio/manifest.json'

/* ---------------------------------------------------------- sustained beds */
/**
 * The site itself, and the low bed under the machine.
 *
 * Both are levelled rather than started and stopped, because a reader
 * scrolling back and forth across the same boundary would otherwise start and
 * stop an oscillator repeatedly — wasteful, and audible.
 */
const roomTone = bed('roomTone', {
  voice: 'roomTone',
  bus: 'ambience',
  peak: AMBIENCE_PEAK,
  trim: AMBIENCE_TRIM,
})

const earthBed = bed('earth', {
  voice: 'assembly',
  bus: 'works',
  peak: EARTH_PEAK,
  trim: EARTH_TRIM,
  epsilon: 0.02,
})

/**
 * How fast earth is moving, 0..1. Silence at 0.
 *
 * Driven by how fast the excavation is ADVANCING rather than by how far
 * through it is, so a parked scrollbar is a quiet site even with a half-open
 * hole on screen, and scrolling back sounds too, because filling a hole in is
 * also earth moving. A named export rather than the bed itself, because the
 * call site should say what the number means.
 */
export function earthLevel(v) {
  earthBed.level(v)
}

/* ------------------------------------------------------------------- api */
/**
 * Hand this route's mix to the engine, then let it read the environment and
 * the stored preference. Creates nothing — no context, no listeners.
 */
export function initAudio() {
  configureAudio({
    storageKey: STORAGE_KEY,
    master: MASTER,
    buses: BUS_LEVELS,
    sounds: SOUNDS,
    essential: ESSENTIAL,
    calibration: CALIBRATION,
    voices: VOICES,
    manifest: MANIFEST,
    confirmId: 'ui.click',
    // The room tone follows audibility exactly: on when sound is actually
    // coming out, gone the moment it is not.
    onAudible: (live) => (live ? roomTone.level(1) : roomTone.stop()),
  })
}

export {
  createChain,
  hasPref,
  isAudible,
  audioState,
  setEnabled,
  sound,
  subscribe,
  teardownAudio,
  toggleEnabled,
}

/** For the calibration tool and the policy tests. */
export const __mix = { SOUNDS, BUS_LEVELS, MASTER, AMBIENCE_PEAK, EARTH_PEAK, dbToGain }
